// swift-tools-version:5.9
//
// The iOS (and macOS) wrapper around the email-chat-view mobile page.
//
// At the repository root because that is where SwiftPM looks when an app adds
// this repo as a package dependency; the sources themselves live under
// `mobile/ios`, next to the Android module. The page it bundles is generated by
// `pnpm build:mobile` and committed, because SwiftPM never runs npm.
import PackageDescription

let package = Package(
    name: "EmailChatView",
    // iOS 16.2 / macOS 13.1 are where WebKit gained `color-mix()`, which the
    // stylesheet uses for its washes and tints.
    platforms: [.iOS("16.2"), .macOS("13.1")],
    products: [
        .library(name: "EmailChatView", targets: ["EmailChatView"]),
    ],
    targets: [
        .target(
            name: "EmailChatView",
            path: "mobile/ios/Sources/EmailChatView",
            resources: [.copy("Resources/email-chat-view.html")]
        ),
        .testTarget(
            name: "EmailChatViewTests",
            dependencies: ["EmailChatView"],
            path: "mobile/ios/Tests/EmailChatViewTests"
        ),
    ]
)
